		if ( 'user' === r.t ) { return T( 'Visitor' ) + ' ' + condOpLabel( r ); }
		if ( COND_KEYED.indexOf( r.t ) > -1 ) { name += ' ' + String( r.k || '' ); }
		return name + ' ' + condOpLabel( r ) + ( COND_NOVALUE.indexOf( r.op ) > -1 ? '' : ' ' + condValueText( r ) );
