					return '<label class="vb-set-check"><input type="checkbox" data-setpref="' + o[ 0 ] + '"' + ( editorPrefs[ o[ 0 ] ] ? ' checked' : '' ) + '><span>' + T( 'Info bar:' ) + ' ' + o[ 1 ] + '</span></label>';
