			var f = { do:'ai_send', doc:docId, text:text, bp:store.state.breakpoint || 'base' };
			if ( AI.useSel && node ) { f.sel = sel; f.sel_label = ( node.name || elLabel( node ) ) + ( node.classes && node.classes.length ? ' ' + node.classes.join( ' ' ) : '' ); }
