				( AI.sending ? '' : '<button type="button" class="vb-btn vb-btn-ghost vb-ai-stop" id="vb-ai-stop"' + ( AI.stopping ? ' disabled' : '' ) + '>' + T( 'Stop' ) + '</button>' ) + '</div>';
