		function click( id ) { return function () { var b = document.getElementById( id ); if ( b ) { b.click(); } }; }
		var A = T( 'Actions' ), P = T( 'Panels' ), V = T( 'View' ), E = T( 'Add element' ), S = T( 'Selected element' );
